from markdown import Extension
from markdown.treeprocessors import Treeprocessor
from markdown.util import etree

class TocTreeprocessor(Treeprocessor):
    def run(self, root):
        toc = etree.Element("div")
        toc.set("class", "toc")
        toc.text = "Table of Contents"
        toc_list = etree.SubElement(toc, "ul")
        toc_list.set("class", "toc-list")
        for child in root:
            if child.tag == "h1" or child.tag == "h2" or child.tag == "h3":
                if min_level <= int(child.tag[1]) <= max_level:
                    toc_item = etree.SubElement(toc_list, "li")
                    toc_item.set("class", "toc-item")
                    toc_link = etree.SubElement(toc_item, "a")
                    toc_link.set("href", "#" + child.get("id"))
                    toc_link.text = child.text
        md.toc = toc

class TocExtension(Extension):
    def extendMarkdown(self, md):
        md.treeprocessors.register(TocTreeprocessor(md), "toc", 100)

md.registerExtension(TocExtension())

