def add_toc_items(state, tokens):
    level = 0
    slug = ''
    title = ''
    for token in tokens:
        if token['type'] == 'heading_open':
            level = int(token['tag'][1])
        elif token['type'] == 'heading_close':
            add_toc_item(state, level, title, slug)
            level = 0
            slug = ''
            title = ''
        elif token['type'] == 'inline':
            text = token['children'][0]['content']
            if level:
                if not slug:
                    slug = text.lower().replace(' ', '-')
                title += text
    if level:
        add_toc_item(state, level, title, slug)

