    for level, items in state.env["toc"].items():
        if level == 1:
            state.write("<div class='toc-wrapper'>")
            state.write("<h4>Table of Contents</h4>")
            state.write("<ul>")
        for title, slug in items:
            state.write(
                "<li><a href='#{slug}'>{title}</a></li>".format(
                    slug=slug, title=title
