from time import sleep
from random import randint

# Determine the threading strategy
if url_store.threading_strategy == 'random':
    # Draw a random URL from the bufferlist
    url_store.download_buffer_lock.acquire()
    if url_store.download_buffer:
        url = url_store.download_buffer.pop(randint(0, len(url_store.download_buffer) - 1))
    else:
        url = None
    url_store.download_buffer_lock.release()
elif url_store.threading_strategy == 'sequential':
    # Draw a sequential URL from the bufferlist
    url_store.download_buffer_lock.acquire()
    if url_store.download_buffer:
        url = url_store.download_buffer.pop(0)
    else:
        url = None
    url_store.download_buffer_lock.release()
else:
    # Draw a random URL from the bufferlist
    url_store.download_buffer_lock.acquire()
    if url_store.download_buffer:
        url = url_store.download_buffer.pop(randint(0, len(url_store.download_buffer) - 1))
    else:
        url = None
    url_store.download_buffer_lock.release()

# If the bufferlist is empty, sleep
if not url:
    sleep(sleep_time)

return url, url_store

