from airflow.hooks.mongo_hook import MongoHook
from airflow.models import BaseOperator
from airflow.utils.decorators import apply_defaults
from airflow.utils.operator_helpers import resolve_connection

class MongoDBHook(MongoHook):
    @apply_defaults
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def get_conn(self):
        return hook.get_conn()

def resolve_mongodb_conn(conn_id):
    conn = resolve_connection(conn_id)
    return MongoDBHook(conn_id=conn.conn_id,
                       conn_type=conn.conn_type,
                       conn_host=conn.host,
                       conn_port=conn.port,
                       conn_login=conn.login,
                       conn_password=conn.password,
                       conn_extra=conn.extra_dejson)

BaseHook.get_connection = resolve_mongodb_conn

def get_mongo_hook(operator, *args, **kwargs):
    conn_id = operator.mongo_conn_id
    return resolve_mongodb_conn(conn_id)

BaseOperator.get_hook = get_mongo_hook

