class SaveStd:
    def __enter__(self):
        self.old_stdin, self.old_stdout, self.old_stderr = sys.stdin, sys.stdout, sys.stderr
        sys.stdin, sys.stdout, sys.stderr = io.StringIO(), io.StringIO(), io.StringIO()

    def __exit__(self, exc_type, exc_val, exc_tb):
        sys.stdin, sys.stdout, sys.stderr = self.old_stdin, self.old_stdout, self.old_stderr
        sys.stdin.flush()
        sys.stdout.flush()
        sys.stderr.flush()

return SaveStd()

