def _walk_model(graphs, stop_at_vars, expand_fn):
    visited = set()
    for graph in graphs:
        if graph in stop_at_vars:
            yield graph
        elif graph not in visited:
            visited.add(graph)
            yield graph
            yield from _walk_model(expand_fn(graph), stop_at_vars, expand_fn)

return _walk_model(graphs, stop_at_vars, expand_fn)

