import os
import socket
import errno

try:
    listen_fds = int(os.environ.get('LISTEN_FDS', '0'))
except ValueError:
    listen_fds = 0

if listen_fds:
    if unset_environment:
        for i in range(listen_fds):
            os.environ.pop('LISTEN_FD' + str(i), None)

    for i in range(listen_fds):
        fd = os.environ.get('LISTEN_FD' + str(i))
        if fd is None:
            continue

        try:
            s = socket.fromfd(int(fd), socket.AF_UNIX, socket.SOCK_STREAM)
            s.close()
        except socket.error as e:
            if e.errno != errno.EBADF:
                raise
            listen_fds -= 1

return listen_fds

