def _first_signal(*signals):
    async def _first_signal_async():
        futures = [Future() for _ in signals]
        for signal, future in zip(signals, futures):
            signal.connect(lambda *args: future.set_result(args[0]), once=True)
        try:
            done, pending = await gather(*futures, return_exceptions=True)
            for future in pending:
                future.cancel()
            for future in done:
                if future.cancelled():
                    continue
                args = future.result()
                if isinstance(args, Exception):
                    raise args
                return args
        except TimeoutError:
            pass

    return _first_signal_async()

