import asyncio
from concurrent.futures import TimeoutError
from asyncio import TimeoutError as AsyncTimeoutError

if loop is None:
    loop = asyncio.get_event_loop()

local_future = asyncio.ensure_future(coroutine, loop=loop)
peer_future = asyncio.ensure_future(peer_coroutine, loop=loop)

try:
    done, pending = loop.run_until_complete(
        asyncio.wait(
            [local_future, peer_future],
            timeout=timeout,
            return_when=asyncio.ALL_COMPLETED,
        )
    )

    if len(done) == 0:
        raise TimeoutError(
            f"Timeout of {timeout} seconds reached while waiting for coroutines to complete."
        )

    if len(done) > 1:
        raise Exception(
            "Multiple coroutines completed at the same time. This should not happen."
        )

    if len(pending) > 0:
        for task in pending:
            task.cancel()

    if local_future in done:
        return local_future.result()

except (asyncio.CancelledError, AsyncTimeoutError):
    raise TimeoutError(
        f"Timeout of {timeout} seconds reached while waiting for coroutines to complete."
    )

