def loop_error_handler(loop, context):
    self.log.append(context["message"])
    loop.default_exception_handler(context)

self.log = []
self.loop.set_exception_handler(loop_error_handler)
try:
    yield
finally:
    self.loop.set_exception_handler(None)
for msg in self.log:
    if re.search(msg_re, msg):
        return
raise AssertionError(f"Expected message '{msg_re}' not found")

def _assert_loop_error_handler_called(loop, context):
    for record in caplog.records:
        if re.match(msg_re, record.message):
