    loop.set_exception_handler(_assert_loop_error_handler_called)
    try:
        yield
    finally:
        loop.set_exception_handler(old_handler)

def exception_handler(loop, context):
    for record in logging.root.manager.disabled_queues:
        if record.getMessage() == msg_re:
            return
    self.fail(f"Expected message '{msg_re}' not found")

loop = asyncio.get_event_loop()
old_handler = loop.get_exception_handler()
loop.set_exception_handler(exception_handler)
try:
    yield
finally:
    loop.set_exception_handler(old_handler)

def _handler(loop, context):
    self.assertTrue(
        any(
            msg_re in msg
