import os
import pathlib
import json
import sys

xdg_dirs = {}

# Get the XDG Base Directory environment variables
for key, value in os.environ.items():
    if key.startswith("XDG_"):
        xdg_dirs[key] = pathlib.Path(value).expanduser()

# Check if the user-dirs.dirs file exists and is parseable
user_dirs_file = xdg_dirs.get("XDG_CONFIG_HOME", pathlib.Path.home() / ".config") / "user-dirs.dirs"
if user_dirs_file.exists():
    try:
        with user_dirs_file.open() as f:
            user_dirs = json.load(f)
    except json.JSONDecodeError:
        sys.stderr.write(f"Error: Could not parse {user_dirs_file}\n")
        sys.exit(1)

    # Update the XDG Base Directories dictionary with the values from the user-dirs.dirs file
    for key, value in user_dirs.items():
        if key in xdg_dirs:
            xdg_dirs[key] = pathlib.Path(value).expanduser()

return xdg_dirs

import os
import pathlib
import json
import logging
logger = logging.getLogger(__name__)
logger.debug("Getting XDG Base Directories")
xdg_dirs = {}
for env_var in os.environ:
    if env_var.startswith("XDG_"):
        xdg_dirs[env_var] = pathlib.Path(os.environ[env_var]).expanduser()
if os.path.exists(os.path.expanduser("~/.config/user-dirs.dirs")):
    try:
        with open(os.path.expanduser("~/.config/user-dirs.dirs"), "r") as f:
            user_dirs = json.load(f)
        for key, value in user_dirs.items():
            xdg_dirs[key] = pathlib.Path(value).expanduser()
    except json.JSONDecodeError as e:
        logger.warning(f"Failed to parse user-dirs.dirs: {e}")
return xdg_dirs

