import os
import yaml
from jsonschema import validate
from jsonschema.exceptions import ValidationError
from jsonschema.exceptions import SchemaError
from pathlib import Path

# Get the directory of the current file
current_dir = Path(__file__).parent.resolve()

# Load the default configuration file
default_config = yaml.safe_load(
    (current_dir / "default.yaml").read_text()
)

# Extend the default configuration with external defaults
for ext_default in ext_defaults:
    default_config.update(
        yaml.safe_load(
            (current_dir / ext_default).read_text()
        )
    )

# Load the configuration files
config = default_config
for file in files:
    config.update(
        yaml.safe_load(
            (current_dir / file).read_text()
        )
    )

# Apply any overrides
for override in overrides:
    config.update(
        yaml.safe_load(
            (current_dir / override).read_text()
        )
    )

# Store the raw configuration
raw_config = config

# Add the external schemas to the list of schemas
schemas = ext_schemas

# Validate the configuration against the schemas
for schema in schemas:
    try:
        validate(instance=raw_config, schema=yaml.safe_load(
            (current_dir / schema).read_text()
        ))
    except ValidationError as err:
        raise ValidationError(err.message)
    except SchemaError as err:
        raise SchemaError(err.message)

return raw_config

