def _rsync_generator(src, dest, flags):
    rsync_cmd = ["rsync"] + flags + [src, dest]
    p = Popen(rsync_cmd, stdout=PIPE, stderr=PIPE)
    while True:
        line = p.stdout.readline()
        if not line:
            break
        yield Command(rsync_cmd, line.decode("utf-8").rstrip())

