import os
import glob
import re

def expand_path(path):
    path = os.path.expanduser(path)
    path = os.path.expandvars(path)
    path = glob.glob(path)
    if len(path) == 1:
        path = path[0]
    return path

def expand_path_list(path_list):
    return [expand_path(path) for path in path_list]

def flatten_list(nested_list):
    return [item for sublist in nested_list for item in sublist]

def expand_path_seq(path_seq):
    return flatten_list(expand_path_list(path_seq))

def expand_path_seqs(path_seqs):
    return [expand_path_seq(path_seq) for path_seq in path_seqs]

return flatten_list(expand_path_seqs(path_seqs))

