def combine_values(opts, key):
    """
    This function takes in a list of options and combines them based on the key. It ignores values of type ClearedValue.
    It iterates through the list of options and adds the value of the key to a list. If the value is a dictionary, it recursively calls combine_opts on the value. If the value is a list, it iterates through the list and calls combine_opts on each element. If the value is a ClearedValue, it skips it.
    :param opts: List of dict. The list of options to combine.
    :param key: str. The key to combine.
    :return: The combined value of the key.
    """
    values = []
    for opt in opts:
        if key in opt:
            value = opt[key]
            if isinstance(value, dict):
                values.append(combine_opts(combiners, value))
            elif isinstance(value, list):
                for v in value:
                    values.append(combine_opts(combiners, v))
            elif not isinstance(value, ClearedValue):
                values.append(value)
    return combiners.get(key, combine_list)(values)

