import os
import pandas as pd
import multiprocessing
from multiprocessing import Pool
from multiprocessing import freeze_support

freeze_support()

def collect_file(file_path):
    return pd.read_csv(file_path, sep="\t", index_col=0)

def merge_files(files):
    df = pd.concat(files, axis=0)
    return df

def accumulate_files(files):
    df = pd.concat(files, axis=0)
    df = df.groupby(df.index).sum()
    return df

def multiprocess_collect(files, num_processes=4, accumulate=False):
    with Pool(num_processes) as pool:
        files = pool.map(collect_file, files)
        if accumulate:
            return accumulate_files(files)
        else:
            return merge_files(files)

def collect_files(directory, pattern, accumulate=False):
    files = [os.path.join(directory, f) for f in os.listdir(directory) if f.endswith(pattern)]
    return multiprocess_collect(files, accumulate=accumulate)

return collect_files(".", "*.db", accumulate=True)

