                for statement in response['PolicyVersion']['Document']['Statement']:
                    if 'Action' in statement:
                        for action in statement['Action']:
                            actions.append(action)
    if 'Marker' in response:
        marker = response['Marker']
    else:
        break
return actions

import json
import os
import requests
import boto3
import botocore

# Retrieve the list of known IAM permissions
try:
    iam_client = boto3.client('iam')
    response = iam_client.list_policies(Scope='Local')
    policies = response['Policies']
    while 'Marker' in response:
        response = iam_client.list_policies(Scope='Local', Marker=response['Marker'])
        policies.extend(response['Policies'])
except botocore.exceptions.ClientError as e:
    print(e)
    return []

# Parse the actions from the policies
actions = set()
for policy in policies:
    try:
        response = iam_client.get_policy(PolicyArn=policy['Arn'])
        policy_document = json.loads(response['Policy']['Document'])
        for statement in policy_document['Statement']:
            if 'Action' in statement:
                if isinstance(statement['Action'], list):
                    actions.update(statement['Action'])
                else:
                    actions.add(statement['Action'])
    except botocore.exceptions.ClientError as e:
        print(e)

# Group the actions by prefix
action_groups = {}
for action in actions:
    prefix = action.split(':')[0]
    if prefix not in action_groups:
        action_groups[prefix] = []
    action_groups[prefix].append(action)

# Return the actions corresponding to the given prefix
if prefix in action_groups:
    return action_groups[prefix]
else:
    return []

