logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

logger.info("Getting IAM actions for prefix: " + prefix)

# Retrieve all known IAM permissions
try:
    response = requests.get("https://awspolicygen.s3.amazonaws.com/js/policies.js")
    response.raise_for_status()
    data = response.json()
except requests.exceptions.RequestException as e:
    logger.error("Error retrieving IAM permissions: " + str(e))
    return []

# Parse the actions from the retrieved permissions
actions = []
for policy in data:
    for statement in policy["Statement"]:
        if "Action" in statement:
            if isinstance(statement["Action"], str):
                actions.append(statement["Action"])
            elif isinstance(statement["Action"], list):
                actions.extend(statement["Action"])

# Group the actions by prefix
actions_by_prefix = {}
for action in actions:
    if action.startswith(prefix):
        actions_by_prefix.setdefault(action, []).append(action)

# Return the actions corresponding to the given prefix
if prefix in actions_by_prefix:
    return actions_by_prefix[prefix]
else:
    return []

