def _get_sequence_name(delta):
    # helper function to get sequence name based on delta
    if delta > 0:
        return "lower"
    elif delta < 0:
        return "upper"
    else:
        return "digit"

def _get_sequence_space(delta):
    # helper function to get sequence space based on delta
    if delta > 0:
        return ord("z") - ord("a") + 1
    elif delta < 0:
        return ord("A") - ord("a") + 1
    else:
        return 10

def _get_ascending(delta):
    # helper function to get ascending based on delta
    if delta > 0:
        return True
    elif delta < 0:
        return False
    else:
        return None

def _get_sequence_name_and_space(delta):
    # helper function to get sequence name and space based on delta
    if delta > 0:
        return "lower", ord("z") - ord("a") + 1
    elif delta < 0:
        return "upper", ord("A") - ord("a") + 1
    else:
        return "digit", 10

def _get_sequence_name_and_space_and_ascending(delta):
    # helper function to get sequence name, space, and ascending based on delta
    if delta > 0:
        return "lower", ord("z") - ord("a") + 1, True
    elif delta < 0:
        return "upper", ord("A") - ord("a") + 1, False
    else:
        return "digit", 10, None

def _get_sequence_name_and_space_and_ascending_and_pattern(delta):
    # helper function to get sequence name, space, ascending, and pattern based on delta
