                    + "\n".join(
                        [
                            f"| `{k}` | `{v}` | {component_metadata['props'][k]['description']} | `{component_metadata['props'][k]['defaultValue']}` | {component_metadata['props'][k]['required']} |"
                            for k, v in valid_kwargs.items()
                        ]
                    )
                ),
                dcc.Markdown("#### Usage"),
                dcc.Markdown(f"```python\n{name}({', '.join(valid_kwargs.keys())})\n```"),
            ]
        )
    }
    components.append(
        {
            "type": component_type,
            "valid_kwargs": valid_kwargs,
            "setup": setup,
        }
    )
return components

