    valid_kwargs = []
    for prop_name, prop_metadata in component_metadata["props"].items():
        if prop_metadata["required"]:
            valid_kwargs.append(prop_name)

    def setup(**kwargs):
        kwargs = _explicitize_kwargs(kwargs, component_metadata)
        for prop_name in kwargs:
            if prop_name not in valid_kwargs:
                raise ValueError(
                    f"Invalid keyword argument '{prop_name}' passed to {name}"
                )
        return _omit(kwargs, ["children"])

    components.append(
        Component(
            type=f"{namespace}.{name}",
            valid_kwargs=valid_kwargs,
            setup=setup,
        )
    )

return components

