    tense = 'hour' if hours == 1 else 'hours'
    return f'{hours} {tense} ago'
elif delta < timedelta(days=7):
    days = int(delta.days)
    tense = 'day' if days == 1 else 'days'
    return f'{days} {tense} ago'
else:
    return tweet_time.strftime('%Y-%m-%d %H:%M:%S')

